#!/usr/bin/env node
/**
 * Replace scratch-parser's runtime AJV compiler with validators generated by
 * the exact AJV version the pinned parser normally uses. This runs after the
 * GUI install and before webpack; the small emitter is vendored in scripts/lib.
 */
import {createHash} from 'node:crypto';
import {copyFileSync, existsSync, readFileSync, writeFileSync} from 'node:fs';
import {createRequire} from 'node:module';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {packAjv6Multi} from './lib/ajv6-standalone.mjs';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const GUI = path.join(ROOT, 'packages', 'scratch-gui');
const PARSER = path.join(GUI, 'node_modules', 'scratch-parser');
const LIB = path.join(PARSER, 'lib');
const STOCK_VALIDATE = path.join(LIB, 'validate-ajv.js');
const VALIDATE = path.join(LIB, 'validate.js');
const MARKER = '// AUTO-GENERATED by scripts/precompile-scratch-parser.mjs';

const expectedHashes = {
    'validate.js': '7e166e48c9c780e20940301e7a113c579e1c5c587c21dbe75e0fed850dc2d3dc',
    'sb2_definitions.json': '41058e96e3c07ced125e588fdc9aac991d2e904003e0fba57b19e6e2862e2a40',
    'sb3_definitions.json': 'd233759589afd530a0d0e68fd6b1d8c1bf897b70c2fb503e08082404ca61c02a',
    'sb2_schema.json': '3d12ecb5495bbaf2c4c8b12991660bda67f6270d812bd45b77f326dd623011d9',
    'sb3_schema.json': '471c37663546e54ede6f7975f58b0e432520c6924195980d4897113bcb246d46',
    'sprite2_schema.json': 'ad57500d5e969aae54f5da2cd7f82614e05da6d7351b8338203114c6832a24f8',
    'sprite3_schema.json': '821e4c04972af894d42f22ac9d6233eb3de3d9b34ef8fc41b977018132bbeff5'
};
const roots = [
    ['sb2-project', 'sb2_schema.json'],
    ['sb3-project', 'sb3_schema.json'],
    ['sb2-sprite', 'sprite2_schema.json'],
    ['sb3-sprite', 'sprite3_schema.json']
];
const hash = value => createHash('sha256').update(value).digest('hex');
const readJson = filename => JSON.parse(readFileSync(path.join(LIB, filename), 'utf8'));

if (!existsSync(PARSER)) throw new Error(`scratch-parser is missing at ${PARSER}; install the GUI first`);
const parserPackage = JSON.parse(readFileSync(path.join(PARSER, 'package.json'), 'utf8'));
if (parserPackage.version !== '5.2.1') throw new Error(`expected scratch-parser 5.2.1, got ${parserPackage.version}`);

const parserRequire = createRequire(path.join(PARSER, 'package.json'));
const ajvPackage = parserRequire('ajv/package.json');
if (ajvPackage.version !== '6.12.6') throw new Error(`expected scratch-parser AJV 6.12.6, got ${ajvPackage.version}`);

for (const [filename, expected] of Object.entries(expectedHashes)) {
    const candidate = filename === 'validate.js' && existsSync(STOCK_VALIDATE) ?
        STOCK_VALIDATE : path.join(LIB, filename);
    const actual = hash(readFileSync(candidate));
    if (actual !== expected) throw new Error(`${filename} hash drift: expected ${expected}, got ${actual}`);
}
if (!existsSync(STOCK_VALIDATE)) copyFileSync(VALIDATE, STOCK_VALIDATE);

const generate = () => {
    const Ajv = parserRequire('ajv');
    const ajv = new Ajv({sourceCode: true});
    ajv.addSchema(readJson('sb2_definitions.json')).addSchema(readJson('sb3_definitions.json'));
    const validators = roots.map(([name, schemaFile]) => ({
        name, validate: ajv.compile(readJson(schemaFile))
    }));
    return [{name: 'precompiled', code: `${MARKER}\n${packAjv6Multi(validators)}\n`}];
};
const generated = generate();
const repeated = generate();
if (JSON.stringify(generated) !== JSON.stringify(repeated)) {
    throw new Error('scratch-parser validator generation is not byte-deterministic');
}
const generatedFiles = [];
for (const {name, code} of generated) {
    if (Buffer.byteLength(code) > 180000) {
        throw new Error(`shared validator source ${Buffer.byteLength(code)} exceeds the 180000-byte P16b preflight`);
    }
    const requires = [...code.matchAll(/require\(['"]([^'"]+)['"]\)/g)].map(match => match[1]);
    const allowedHelpers = new Set(['ajv/lib/compile/equal', 'ajv/lib/compile/ucs2length']);
    const unexpected = requires.filter(request => !allowedHelpers.has(request));
    if (unexpected.length) {
        throw new Error(`${name} generated unexpected runtime imports: ${unexpected.join(', ')}`);
    }
    const output = path.join(LIB, `validate-${name}.js`);
    writeFileSync(output, code);
    generatedFiles.push({name, bytes: Buffer.byteLength(code), sha256: hash(code), requires});
}

const wrapper = `${MARKER}
'use strict';
var validators = require('./validate-precompiled');
var validateSb2Project = validators['sb2-project'];
var validateSb3Project = validators['sb3-project'];
var validateSb2Sprite = validators['sb2-sprite'];
var validateSb3Sprite = validators['sb3-sprite'];

module.exports = function (isSprite, input, callback) {
    var validateSb2 = isSprite ? validateSb2Sprite : validateSb2Project;
    var validateSb3 = isSprite ? validateSb3Sprite : validateSb3Project;
    if (validateSb2(input)) {
        input.projectVersion = 2;
        return callback(null, input);
    }
    if (validateSb3(input)) {
        input.projectVersion = 3;
        return callback(null, input);
    }
    callback({
        validationError: 'Could not parse as a valid SB2 or SB3 project.',
        sb2Errors: validateSb2.errors,
        sb3Errors: validateSb3.errors
    });
};
`;
writeFileSync(VALIDATE, wrapper);
console.log(JSON.stringify({scratchParser: parserPackage.version, ajv: ajvPackage.version,
    generator: 'vendored-ajv-pack-0.3.1-subset',
    wrapperBytes: Buffer.byteLength(wrapper), generatedFiles}));
